list_shipping_profiles.code:
const response = await client.shippingProfiles.listShippingProfiles({search: 'metro', sort: 'name', order: 'asc', limit: 20});
for (const profile of response.map.shipping_profiles) {
    console.log(profile.id, profile.name, profile.rule_preference, profile.rules_count);
}
console.log(response.map.pagination.total, response.map.pagination.has_next);

