create_shipping_profile_wizard.code:
const response = await client.shippingProfiles.createShippingProfileWizard({
    shipping_profile: {
        name: 'Wizard profile',
        description: 'Built in one call',
        rule_preference: 'product_assigned_rule',
        shipping_rules: [
            {
                name: 'Metro delivery',
                description: 'Metro deliveries',
                shipping_class: 2,
                zones: [{id: 5}, {name: 'Inner West'}],
                shipping_rate: {
                    name: 'Metro flat rate',
                    method: 'flat_rate',
                    shipping_cost: {amount: 10, type: 'fixed'},
                    handling_cost: {amount: 5, type: 'percent'},
                },
            },
        ],
    },
});
const profile = response.map.shipping_profile;
console.log(response.statusCode, profile.id, profile.name, profile.rules_count);

